const items = $input.all();

return items.map(item => {
  const data = item.json;

  const fullName = String(data["Full Name"] || "").trim();
  const email = String(data["Email"] || "").trim();
  const title = String(data["Meeting Title"] || "").trim();
  const purpose = String(data["Meeting Purpose"] || "").trim();
  const date = String(data["Preferred Date"] || "").trim();
  const time = String(data["Preferred Time"] || "").trim();

  const durationRaw = data["Duration(Minutes)"];
  const duration = Number(durationRaw || 30);

  // -----------------------------
  // VALIDATION
  // -----------------------------

  if (!fullName) {
    throw new Error("Full Name is required");
  }

  if (!email || !email.includes("@")) {
    throw new Error("Valid email is required");
  }

  if (!title) {
    throw new Error("Meeting Title is required");
  }

  if (!date) {
    throw new Error("Preferred Date is required");
  }

  if (!time) {
    throw new Error("Preferred Time is required");
  }

  if (!Number.isFinite(duration) || duration <= 0) {
    throw new Error("Duration must be a valid positive number");
  }

  // -----------------------------
  // PARSE DATE
  // Expected: 9/17/2026
  // -----------------------------

  const dateMatch = date.match(
    /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
  );

  if (!dateMatch) {
    throw new Error(
      `Invalid date format: ${date}. Expected M/D/YYYY`
    );
  }

  const month = Number(dateMatch[1]);
  const day = Number(dateMatch[2]);
  const year = Number(dateMatch[3]);

  if (month < 1 || month > 12) {
    throw new Error("Invalid month");
  }

  if (day < 1 || day > 31) {
    throw new Error("Invalid day");
  }

  // -----------------------------
  // PARSE TIME
  // Supports:
  // 11:00 AM
  // 11:00:00 AM
  // -----------------------------

  const timeMatch = time.match(
    /^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)$/i
  );

  if (!timeMatch) {
    throw new Error(
      `Invalid time format: ${time}. Expected HH:MM AM/PM`
    );
  }

  let hour = Number(timeMatch[1]);
  const minute = Number(timeMatch[2]);
  const second = Number(timeMatch[3] || 0);
  const ampm = timeMatch[4].toUpperCase();

  if (hour < 1 || hour > 12) {
    throw new Error("Invalid hour");
  }

  if (minute < 0 || minute > 59) {
    throw new Error("Invalid minute");
  }

  if (second < 0 || second > 59) {
    throw new Error("Invalid second");
  }

  // Convert 12-hour → 24-hour
  if (ampm === "PM" && hour !== 12) {
    hour += 12;
  }

  if (ampm === "AM" && hour === 12) {
    hour = 0;
  }

  // -----------------------------
  // INDIA TIME
  // -----------------------------

  const localDateTime =
    `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}` +
    `T${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}:${String(second).padStart(2, "0")}`;

  // Asia/Kolkata = UTC+05:30
  const start = new Date(`${localDateTime}+05:30`);

  if (isNaN(start.getTime())) {
    throw new Error("Invalid meeting start date/time");
  }

  const end = new Date(
    start.getTime() + duration * 60 * 1000
  );

  // -----------------------------
  // RETURN
  // -----------------------------

  return {
    json: {
      ...data,

      fullName,
      email,
      title,
      purpose,

      date,
      time,
      duration,

      timeZone: "Asia/Kolkata",

      startTime: start.toISOString(),
      endTime: end.toISOString(),

      status: "Checking Availability"
    }
  };
});

const calendarItems = $input.all();
const request = $('Code in JavaScript').first().json;

const requestedStart = new Date(request.startTime);
const requestedEnd = new Date(request.endTime);

if (isNaN(requestedStart.getTime()) || isNaN(requestedEnd.getTime())) {
  throw new Error("Invalid meeting start or end time");
}

// Check actual calendar events
const conflictingEvents = calendarItems.filter(item => {
  const event = item.json;

  // Ignore empty output from Always Output Data
  if (!event.id && !event.htmlLink && !event.eventId) {
    return false;
  }

  // Google Calendar event start/end
  const eventStart =
    event.start?.dateTime ||
    event.start?.date;

  const eventEnd =
    event.end?.dateTime ||
    event.end?.date;

  // If event doesn't contain start/end, don't count it
  if (!eventStart || !eventEnd) {
    return false;
  }

  const existingStart = new Date(eventStart);
  const existingEnd = new Date(eventEnd);

  if (
    isNaN(existingStart.getTime()) ||
    isNaN(existingEnd.getTime())
  ) {
    return false;
  }

  // OVERLAP CHECK
  return (
    requestedStart < existingEnd &&
    requestedEnd > existingStart
  );
});

const isBusy = conflictingEvents.length > 0;

return [
  {
    json: {
      ...request,

      available: !isBusy,
      busy: isBusy,

      eventCount: conflictingEvents.length,

      availabilityStatus: isBusy
        ? "Busy"
        : "Available",

      conflictingEvents: conflictingEvents.map(item => ({
        id: item.json.id || item.json.eventId || "",
        summary: item.json.summary || "",
        start: item.json.start?.dateTime || item.json.start?.date || "",
        end: item.json.end?.dateTime || item.json.end?.date || ""
      }))
    }
  }
];
